use vstd::prelude::*;

verus! {
    // reverse: given a vector of i32, returns a new vector
    // which is the input reversed.
    //
    // Postcondition:
    //   1. The result has the same length as the input.
    //   2. For every index i in [0, n), result[i] = a[n-1-i].
    fn reverse(a: &Vec<i32>) -> (a_rev: Vec<i32>)
        ensures
            a_rev.len() == a.len(),
            forall |i: int| 0 <= i && i < a.len() as int ==>
                a_rev[i as usize] == a[(a.len() - 1 - i as usize)],
    {
        let n: usize = a.len();
        let mut rev: Vec<i32> = Vec::new();
        let mut i: usize = 0;
        // We build rev by pushing a[n-1], a[n-2], ..., a[0].
        // Invariant after k steps (i == k):
        //   1. 0 <= k <= n
        //   2. rev.len() == k
        //   3. for all 0 <= j < k, rev[j] == a[n-1-j]
        while i < n
            invariant
                i <= n,
                rev.len() == i,
                forall |j: int| 0 <= j && j < i as int ==>
                    rev[j as usize] == a[(n - 1 - j as usize)],
            decreases n - i,
        {
            // compute the index in `a` we want to push
            let idx: usize = n - 1 - i;
            // idx < n because i < n, so subtraction is safe
            rev.push(a[idx]);
            i = i + 1;
        }
        rev
    }
}

